function hm_json(array $value): string { return json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR); }
function hm_write(string $path, array $value): string {
    $raw = hm_json($value) . "\n";
    $fh = fopen($path, 'x'); if ($fh === false) throw new RuntimeException('durable_create_failed');
    fwrite($fh, $raw); fflush($fh); fclose($fh);
    if ((string)file_get_contents($path) !== $raw) throw new RuntimeException('durable_readback_failed');
    return hash('sha256', $raw);
}
function hm_one(PDO $db, string $sql, array $params): ?array { $s=$db->prepare($sql); $s->execute($params); $r=$s->fetch(PDO::FETCH_ASSOC); return $r===false?null:$r; }
function hm_many(PDO $db, string $sql, array $params): array { $s=$db->prepare($sql); $s->execute($params); return $s->fetchAll(PDO::FETCH_ASSOC); }
function hm_first(array $row, array $keys): string { foreach($keys as $k){ if(isset($row[$k]) && is_scalar($row[$k]) && trim((string)$row[$k])!=='') return trim((string)$row[$k]); } return ''; }
function hm_num(mixed $v): ?float { if($v===null || !is_scalar($v) || !is_numeric((string)$v)) return null; $n=(float)$v; return is_finite($n)?$n:null; }
function hm_coords(array $row): array {
    foreach ([['latitude','longitude'],['lat','lng'],['lat','lon'],['api_latitude','api_longitude'],['hotelLatitude','hotelLongitude']] as [$a,$b]) {
        $lat=hm_num($row[$a]??null); $lon=hm_num($row[$b]??null);
        if($lat!==null && $lon!==null && abs($lat)<=90 && abs($lon)<=180) return [$lat,$lon];
    }
    return [null,null];
}
function hm_distance(?float $a,?float $b,?float $c,?float $d): ?float {
    if($a===null||$b===null||$c===null||$d===null) return null;
    $r=6371.0088; $p1=deg2rad($a); $p2=deg2rad($c); $dp=deg2rad($c-$a); $dl=deg2rad($d-$b);
    $x=sin($dp/2)**2+cos($p1)*cos($p2)*sin($dl/2)**2; return round(2*$r*asin(min(1,sqrt($x))),3);
}

